python.code:
intervals.sort()
merged = []
for start, end in intervals:
    if not merged or start > merged[-1][1]:
        merged.append([start, end])
    else:
        merged[-1][1] = max(merged[-1][1], end)

java.code:
intervals.sort(Comparator.comparingInt(a -> a[0]));
List<int[]> merged = new ArrayList<>();
for (int[] cur : intervals) {
    if (merged.isEmpty() || cur[0] > merged.get(merged.size()-1)[1]) merged.add(cur);
    else merged.get(merged.size()-1)[1] = Math.max(merged.get(merged.size()-1)[1], cur[1]);
}

javascript.code:
intervals.sort((a, b) => a[0] - b[0]);
const merged = [];
for (const [start, end] of intervals) {
  if (!merged.length || start > merged.at(-1)[1]) merged.push([start, end]);
  else merged.at(-1)[1] = Math.max(merged.at(-1)[1], end);
}

cpp.code:
std::sort(intervals.begin(), intervals.end());
std::vector<std::vector<int>> merged;
for (auto cur : intervals) {
    if (merged.empty() || cur[0] > merged.back()[1]) merged.push_back(cur);
    else merged.back()[1] = std::max(merged.back()[1], cur[1]);
}
